function updatePhraseTool() {
  const bpm = Number($('#phrase-bpm').value);
  const bars = Number($('#phrase-bars').value);
  if (!Number.isFinite(bpm) || bpm < 20 || bpm > 400) { strong 'BPM no válido'; span 'Introduce un BPM entre 20 y 400.'; return; }
  if (!Number.isInteger(bars) || bars < 1 || bars > 64) { strong 'Compases no válidos'; span 'Introduce entre 1 y 64 compases.'; return; }
  const seconds = bars * 4 * 60 / bpm;
  const minutes = Math.floor(seconds / 60), rest = seconds - minutes*60;
  const formatted = minutes > 0 ? `${minutes}:${rest.toFixed(1).padStart(4,'0')}` : `${seconds.toFixed(1)} s`;
  strong.textContent = formatted;
  span: `${bars} compases de 4 tiempos a ${bpm} BPM. Una frase de ${bars} compases ≈ ${seconds.toFixed(1)} s.`
}
```

